  "hb.m.stateHint.forbidden": { ko: "이 클러스터 연결의 신원에 작업 영역의 Monitoring Data Reader 역할이 필요합니다.", en: "This cluster's connection identity needs Monitoring Data Reader on the workspace." },
  "hb.m.stateHint.throttled": { ko: "같은 신원이 30초 동안 보낸 질의량이 한도를 넘었습니다 — 잠시 뒤 다시 시도하세요.", en: "This identity's queries over 30 seconds went over the limit — try again shortly." },
  "hb.m.stateHint.tooCostly": { ko: "다시 시도해도 같은 결과입니다(비용 = 시계열 수 × 기간 ÷ 수집 간격 ÷ 5000, 상한 15,000). 기간을 줄이거나 레코딩 규칙으로 시계열 수를 줄여야 합니다 — 어느 화면인지 알려 주시면 대시보드가 그 질의를 나눠 묻도록 고칩니다.", en: "Retrying gives the same answer (cost = series × range ÷ scrape interval ÷ 5000, limit 15,000). Shorten the range or cut the series with a recording rule — tell us which view so the dashboard splits that query." },
  "hb.m.stateHint.failed": { ko: "잠시 뒤 다시 시도하세요.", en: "Try again shortly." },
  "hb.m.notMeasured": { ko: "미측정", en: "Not measured" },
  "hb.m.window": { ko: "기간", en: "Window" },
  "hb.m.minutes": { ko: "{n}분", en: "{n} min" },
  "hb.m.refresh": { ko: "새로 고침", en: "Refresh" },
  "hb.m.windowFit": { ko: "Hubble 지표는 {n}분 창으로 읽음", en: "Hubble metrics read a {n}-minute window" },
  "hb.m.windowFitHint": { ko: "Hubble 지표 창은 5·15·60·360분 — 범위를 덮는 가장 가까운 창, 끝은 지금", en: "Hubble metric windows are 5, 15, 60, 360 min — the nearest covering the range, ending now" },
  "hb.past.hintLoki": { ko: "흐름 표본·지표는 지금 것만 읽습니다(노드 버퍼는 몇 분, Hubble UI는 최근 표본). 대신 Loki(hubble-flow-exporter)가 며칠 보관하는 드롭 흐름은 아래에서 그 구간 그대로 봅니다 — 드롭만, 허용된 흐름은 없음.", en: "Flow samples and metrics are read now only (node buffers keep minutes, the Hubble UI a recent sample). The dropped flows Loki keeps for days (hubble-flow-exporter) are shown below for that span — drops only, no allowed flows." },
  "hb.past.window": { ko: "드롭 창은 {w}(가장 가까운 창).", en: "Drop window: {w} (the nearest)." },
  "hb.past.title": { ko: "Hubble은 지금 것만", en: "Hubble shows now only" },
  "hb.past.hint": { ko: "Hubble 흐름 표본은 각 노드 버퍼(최근 몇 분)에서, 지표는 지금을 끝으로 읽습니다 — 지난 구간의 흐름은 Loki(hubble-flows)·VNet 흐름 로그에서 보세요", en: "Hubble flow samples come from each node's buffer (the last few minutes) and metrics end now — past flows are in Loki (hubble-flows) and VNet flow logs" },
  "hb.m.basis": { ko: "최근 {n}분 동안 Hubble 메트릭이 센 값입니다(조회 {at}). Prometheus increase()는 보간하므로 근삿값입니다.", en: "Counted by Hubble metrics over the last {n} minutes (read {at}). Prometheus increase() extrapolates, so values are approximate." },
  "hb.m.scopeAlias": { ko: "작업 영역의 cluster 라벨이 '{cluster}' 하나뿐이라 이 클러스터 것으로 봤습니다.", en: "The workspace has a single cluster label '{cluster}', taken as this cluster." },
  "hb.m.scopeNone": { ko: "작업 영역 메트릭에 cluster 라벨이 없어 작업 영역 전체 값입니다.", en: "The workspace metrics have no cluster label: values cover the whole workspace." },
  "hb.m.lost": { ko: "잃은 이벤트 {n}건", en: "{n} events lost" },
  "hb.m.lostHint": { ko: "Hubble이 처리하지 못하고 버린 이벤트가 있어 아래 수는 실제보다 적을 수 있습니다.", en: "Hubble dropped events it could not process, so the counts below may be understated." },
  "hb.m.missing": { ko: "수집되지 않는 메트릭: {list} — 해당 칸은 '미측정'.", en: "Not collected: {list} — those fields show 'not measured'." },
  "hb.m.truncated": { ko: "행이 많아 일부만 반영했습니다.", en: "Too many series: only part is shown." },
  "hb.m.gridTitle": { ko: "워크로드 {n}개", en: "{n} workloads" },
  "hb.m.noEdges": { ko: "연결선 없음", en: "No edges" },
  "hb.m.noEdgesHint": { ko: "메트릭은 출발 또는 도착 하나만 기록해서 '누가 누구와' 통신했는지 알 수 없습니다. 짐작해서 선을 긋지 않습니다 — 연결선은 아래 ACNS 흐름 로그를 켜면 보입니다.", en: "Metrics name one side only, so who talks to whom is unknown. No lines are guessed — enable ACNS flow logs below for edges." },
  "hb.m.namespace": { ko: "네임스페이스", en: "Namespace" },
