  "hb.m.kindUnknown": { ko: "종류 미확인", en: "Kind unknown" },
  "hb.m.byPattern": { ko: "이름으로 추정", en: "From the name" },
  "hb.m.pods": { ko: "파드 {n}", en: "{n} pods" },
