  "hb.m.received": { ko: "받은 이벤트", en: "Received events" },
  "hb.m.drops": { ko: "드롭", en: "Drops" },
  "hb.m.dnsErrors": { ko: "DNS 오류", en: "DNS errors" },
  "hb.m.unattributed": { ko: "워크로드로 묶지 못한 이벤트 — 보냄 {egress} · 받음 {ingress} · 양쪽 라벨 없음(호스트·외부) {none}", en: "Events not tied to a workload — sent {egress} · received {ingress} · no side label (host, world) {none}" },
  "hb.m.verdict.forwarded": { ko: "전달", en: "Forwarded" },
  "hb.m.verdict.dropped": { ko: "드롭", en: "Dropped" },
  "hb.m.verdict.redirected": { ko: "프록시로 전달 (DNS 등)", en: "Redirected (DNS proxy …)" },
  "hb.m.verdict.error": { ko: "오류", en: "Error" },
  "hb.m.eventsNotFlows": { ko: "관측 지점마다 세는 Hubble 이벤트 수입니다 — 연결 수가 아닙니다.", en: "Hubble events counted at each observation point — not connections." },
  "hb.m.protocols": { ko: "프로토콜", en: "Protocols" },
  "hb.m.namespaces": { ko: "네임스페이스별", en: "By namespace" },
  "hb.m.dnsTitle": { ko: "DNS 오류 응답", en: "DNS error responses" },
  "hb.m.noDnsErrors": { ko: "DNS 오류 응답 없음", en: "No DNS error responses" },
  "hb.m.rcode": { ko: "응답 코드", en: "Response code" },
  "hb.m.workload": { ko: "워크로드", en: "Workload" },
  "hb.m.side": { ko: "쪽", en: "Side" },
  "hb.m.count": { ko: "수", en: "Count" },
  "hb.m.side.server": { ko: "DNS 서버", en: "DNS server" },
  "hb.m.side.client": { ko: "요청한 파드", en: "Client pod" },
  "hb.m.nxdomainHint": { ko: "CoreDNS의 '없는 도메인' 응답이 많으면 대부분 Kubernetes 기본 ndots:5가 검색 접미사를 먼저 붙여 물어본 것입니다 — 외부 이름만 부르는 파드는 dnsConfig ndots 1로 줄일 수 있습니다.", en: "Many 'non-existent domain' answers from CoreDNS usually come from the Kubernetes default ndots:5 trying search suffixes first — pods that call only external names can cut them with dnsConfig ndots 1." },
  "hb.m.dropsByReason": { ko: "드롭 이유", en: "Drop reasons" },
  "hb.m.noDrops": { ko: "드롭 없음", en: "No drops" },
  "hb.m.policyDenied": { ko: "정책에 막힌 워크로드 (policy_denied)", en: "Workloads blocked by policy (policy_denied)" },
  "hb.m.noPolicyDenied": { ko: "정책에 막힌 트래픽 없음", en: "No traffic blocked by policy" },
  "hb.m.verdictEvents": { ko: "정책 판정 이벤트 (새 연결)", en: "Policy verdict events (new connections)" },
  "hb.m.readinessTitle": { ko: "'강제하면 막힐 연결'은 메트릭으로 알 수 없음", en: "'What enforcing would block' is not in the metrics" },
  "hb.m.readinessHint": { ko: "메트릭의 정책 판정에는 '허용한 규칙'이 없어 관찰본 정책이 허용한 것과 모두 허용(allow-any)으로 통과한 것을 구분할 수 없습니다. ACNS 흐름 로그를 켜거나, 문서(docs/deployment/kubernetes.md '관찰 → 강제 전환 판단')의 hubble observe 명령으로 확인하세요.", en: "Metric verdicts carry no allowing rule, so policy-allowed and allow-any traffic look the same. Enable ACNS flow logs, or use the hubble observe recipe in docs/deployment/kubernetes.md (audit → enforce)." },
  "hb.m.noFlows": { ko: "개별 흐름은 메트릭에 없음", en: "Individual flows are not in the metrics" },
  "hb.m.noFlowsHint": { ko: "흐름 목록은 ACNS 흐름 로그(또는 Hubble exec)가 있어야 보입니다.", en: "The flow list needs ACNS flow logs (or Hubble exec)." },
  "hb.fl.title": { ko: "연결선·흐름을 보려면: ACNS 흐름 로그 켜기", en: "For edges and flows: enable ACNS flow logs" },
  "hb.fl.why": { ko: "클러스터 관리자가 아래 리소스를 클러스터에 적용하면 출발→도착·판정·적용 정책이 Log Analytics(ContainerNetworkLogs)에 쌓이고, 이 화면이 자동으로 그 로그를 씁니다. 대시보드는 클러스터에 쓰지 않습니다(복사만).", en: "When the cluster owner applies the resource below, source→destination, verdict and policies land in Log Analytics (ContainerNetworkLogs) and this view uses them automatically. The dashboard never writes to the cluster (copy only)." },
  "hb.fl.step1": { ko: "ACNS 컨테이너 네트워크 로그 수집을 켭니다(Container Insights 연결 — Microsoft Learn 'Container network logs').", en: "Turn on ACNS container network logs collection (Container Insights — Microsoft Learn 'Container network logs')." },
  "hb.fl.step2": { ko: "아래 ContainerNetworkLog의 라벨 선택자를 볼 앱으로 좁혀 GitOps로 적용합니다.", en: "Narrow the label selectors below to the apps to watch and apply it through GitOps." },
  "hb.fl.step3": { ko: "수 분 뒤 데이터 출처가 'ACNS 흐름 로그'로 바뀝니다.", en: "Within minutes the source switches to 'ACNS flow logs'." },
  "hb.fl.copy": { ko: "YAML 복사", en: "Copy YAML" },
  "hb.fl.copied": { ko: "복사됨", en: "Copied" },
  "hb.fl.cost": { ko: "비용: 기록 1건마다 Log Analytics 수집 요금 — DNS가 가장 많으니 필터를 좁게 두세요.", en: "Cost: each record is billed as Log Analytics ingestion — DNS dominates, so keep the filters narrow." },
