  "ob.ds.role.prometheus": { ko: "관리형 Prometheus — 클러스터의 데이터 수집 규칙이 가리키는 Azure Monitor 작업 영역에서 읽음", en: "Managed Prometheus — read from the Azure Monitor workspace the cluster's data collection rule points to" },
