  "ob.ds.role.loki": { ko: "Loki — 연결 파일 aks.observability.loki로 클러스터 안에서 읽음 (워크로드 로그·Hubble 드롭, 운영자만)", en: "Loki — read in-cluster through aks.observability.loki in the connections file (workload logs, Hubble drops; operators only)" },
  "ob.ds.role.tempo": { ko: "Tempo — 읽지 않음, Grafana Explore 링크만", en: "Tempo — not read, Grafana Explore links only" },
  "ob.ds.role.pyroscope": { ko: "Pyroscope — 읽지 않음, Grafana Explore 링크만", en: "Pyroscope — not read, Grafana Explore links only" },
  "ob.ds.role.grafana": { ko: "Azure Managed Grafana — 링크만, 아무것도 읽지 않음 (aks.observability.grafana)", en: "Azure Managed Grafana — links only, nothing read (aks.observability.grafana)" },
  "ob.ds.why.blocked": { ko: "연결 거부 또는 시간 초과 — 보통 Loki 네임스페이스의 네트워크 정책이 대시보드 파드를 막음 (허용 규칙은 워크로드 상세)", en: "Refused or timed out — usually the Loki namespace's network policy blocks the dashboard pod (the allow rule is in the workload detail)" },
  "ob.ds.why.error": { ko: "응답했지만 준비 안 됨 ({detail})", en: "Answered but not ready ({detail})" },
  "ob.ds.why.notRead": { ko: "이 클러스터에서 읽은 데이터 없음 — 작업 영역 연결 없음 또는 조회 실패", en: "No data read for this cluster — no workspace link, or the query failed" },
  "ob.ds.why.linkHint": { ko: "연결 파일의 aks.observability.grafana에 데이터 소스 UID를 넣으면 링크가 생김", en: "Add the datasource UID to aks.observability.grafana in the connections file to get a link" },
  "ob.ds.pipeline.seen": { ko: "수집: 작업 영역 지표에 이 소스로 보내는 흔적 있음 (관측 스택)", en: "Collection: the workspace metrics show shipping to this source (observability stack)" },
