  "ob.pl.footLoki": { ko: "줄을 누르면 전체 내용 · Indexed labels · Structured metadata · 앞뒤 맥락이 열립니다. 민감한 값은 가린 뒤 보여 줍니다.", en: "Open a line for its full text, indexed labels, structured metadata and context. Sensitive values are masked." },
  "ob.pl.foot": { ko: "줄을 누르면 전체 내용이 열립니다. 라벨·맥락은 Loki에서 읽은 줄에만 있습니다.", en: "Open a line for its full text. Labels and context exist for Loki lines only." },
  "ob.bl.title": { ko: "열 · 값 구성", en: "Columns · values" },
  "ob.bl.sub": { ko: "블록 {n}/{max} — 표의 열이 되고, 히트맵 타일에 띄울 값 목록이 됩니다", en: "{n}/{max} blocks — the table's columns and the values a heatmap tile can show" },
  "ob.bl.foot": { ko: "'—' = 그 종류가 아니거나 지표를 내보내지 않음(0이 아님). 점선 블록 = 이 클러스터 작업 영역에 그 지표가 없음 — 아래 가이드에서 내보내는 방법을 봅니다. '저장'을 누르면 이 브라우저에 남습니다.", en: "'—' = not that kind, or the metric is not exposed (not zero). A dashed block = the metric is not in this cluster's workspace — the guide below says how to expose it. Your blocks are remembered in this browser." },
