  "ob.bl.group.app": { ko: "앱 종류 · 앱 지표 (타일 글자)", en: "App kind · app metrics (tile text)" },
  "ob.bl.lensHint": { ko: "타일 색 = 종합 상태 그대로, 타일 글자 = {name}. 시계열이 없으면 '—'입니다(0 아님).", en: "Tile colour = the overall state as before, tile text = {name}. No series = '—' (not 0)." },
  "ob.bl.kindLong": { ko: "앱 런타임 (Java · Node.js · Go …)", en: "App runtime (Java · Node.js · Go …)" },
  "ob.bl.kindHint": { ko: "이 워크로드가 어떤 런타임의 애플리케이션인지 — 추정하지 않고 근거가 있는 것만: 런타임 지표(파란 칩, 버전 포함) · OpenTelemetry SDK 보고 · 매니페스트에 선언된 실행 명령/런타임 설정 · Defender 이미지 스캔 · Docker Hub 공식 이미지(회색 칩). 칩에 마우스를 올리면 근거가 나옵니다. Deployment 같은 Kubernetes 종류는 이름 옆에 있습니다.", en: "Which runtime the workload's application is — never guessed, evidence only: the runtime's own metrics (blue chip, with the version) · the OpenTelemetry SDK · the executable / runtime setting the manifest declares · Defender's image scan · a Docker Hub official image (grey chip). Hover a chip for its evidence. The Kubernetes kind (Deployment …) is next to the name." },
