  "ob.bl.guideTitle": { ko: "종류별 가이드", en: "Guide per kind" },
  "ob.bl.guideSub": { ko: "어떤 애플리케이션인지 · 지표를 보려면 무엇이 필요한지", en: "What it is · what its metrics need" },
  "ob.bl.guideFoot": { ko: "대시보드는 클러스터의 Azure Monitor 작업 영역에 이미 있는 지표만 읽습니다 — 애플리케이션이나 수집기 설정을 바꾸지 않습니다. 코드는 복사용 예시입니다.", en: "The dashboard only reads what is already in the cluster's Azure Monitor workspace — it changes neither the application nor the collector. The code is an example to copy." },
  "ob.bl.g.here": { ko: "이 클러스터", en: "This cluster" },
  "ob.bl.g.hereN": { ko: "지표로 확인된 워크로드 {n}개", en: "{n} workloads confirmed by metrics" },
  "ob.bl.g.hereNone": { ko: "작업 영역에 {metric} 지표가 없습니다 — 이 종류의 지표를 내보내는 워크로드가 없거나 수집되지 않습니다", en: "No {metric} in the workspace — no workload exposes this kind's metrics, or they are not collected" },
  "ob.bl.g.hinted": { ko: "지표 없이 다른 근거(매니페스트·이미지 스캔 등)로 확인 {n}개", en: "{n} known by other evidence (manifest · image scan …), no metrics" },
  "ob.bl.g.detect": { ko: "알아보는 근거", en: "Recognised by" },
  "ob.bl.g.detectHint": { ko: "이 지표가 파드에서 나오면 그 종류이고 버전도 함께 읽습니다. 지표가 없으면 매니페스트 선언·이미지 스캔 같은 다른 근거가 있을 때만 표시합니다(이름으로 추정하지 않음).", en: "A pod exposing this metric is that kind, and its version is read too. Without it, the kind is shown only on other evidence (manifest, image scan) — never guessed from a name." },
  "ob.bl.g.library": { ko: "지표를 내보내는 것", en: "Exposed by" },
  "ob.bl.g.columns": { ko: "쓸 수 있는 블록", en: "Blocks" },
  "ob.bl.g.needs": { ko: "필요한 것", en: "What it needs" },
  "ob.bl.g.step1": { ko: "기능: 애플리케이션에 {library}를 붙여 /metrics를 엽니다 (오른쪽 예시).", en: "Feature: add {library} to the application and open /metrics (example on the right)." },
  "ob.bl.g.step2": { ko: "환경 설정: 수집기(Alloy 또는 ama-metrics)가 그 파드를 수집하게 합니다 — 파드 주석 또는 PodMonitor. 지표에 namespace · pod 라벨이 붙어야 워크로드에 연결됩니다.", en: "Configuration: let the collector (Alloy or ama-metrics) scrape the pod — pod annotations or a PodMonitor. The metrics need namespace · pod labels to be tied to the workload." },
  "ob.bl.g.step3": { ko: "권한: 추가 권한은 없습니다 — 이 화면의 다른 지표와 같은 '작업 영역 Monitoring Data Reader'로 읽습니다. 클러스터 접속(Kubernetes 권한)은 쓰지 않습니다.", en: "Permissions: none extra — read with the same 'Monitoring Data Reader on the workspace' as the other metrics here. No Kubernetes access is used." },
  "ob.bl.g.step4": { ko: "확인: 수집 간격(30–60초) 뒤 새로 고치면 '종류'가 확정으로 바뀌고 블록에 값이 나옵니다.", en: "Check: after a scrape interval (30–60 s) refresh — the kind is confirmed and the blocks show values." },
  "ob.bl.g.snippet": { ko: "{library} — 지표 내보내기", en: "{library} — exposing the metrics" },
  "ob.bl.g.scrape": { ko: "수집 — 파드 주석", en: "Collection — pod annotations" },
  "ob.bl.noneTitle": { ko: "런타임 지표를 내보내지 않는 워크로드 {n}개 — 파란 칩은 다른 근거로 종류를 확인한 것, 회색은 근거 없음입니다.", en: "{n} workloads exposing no runtime metric — blue = kind known by other evidence, grey = no evidence." },
  "ob.bl.noneHinted": { ko: "{kind} ({basis}) — 지표를 내보내면 값과 버전이 나옵니다", en: "{kind} ({basis}) — expose metrics to get values and the version" },
