  "ob.hm.loki.notConfigured": { ko: "Loki 연결 설정 없음", en: "Loki not configured" },
  "ob.hm.loki.unreachable": { ko: "Loki에 닿지 않음", en: "Loki unreachable" },
  "ob.hm.loki.failed": { ko: "Loki 조회 실패", en: "Loki query failed" },
  "ob.hm.lokiHint.notConfigured": { ko: "연결 파일의 aks.observability.loki에 클러스터 안 Loki 주소(예: http://<loki-svc>.<namespace>:3100)를 적으면 이 워크로드의 로그가 여기 나옵니다.", en: "Put the in-cluster Loki URL (e.g. http://<loki-svc>.<namespace>:3100) under aks.observability.loki in the connections file to see this workload's logs here." },
  "ob.hm.lokiHint.unreachable": { ko: "연결 자체가 안 됩니다(거부·경로 없음·이름 없음·연결 시간 초과 — 연결 전 단계). 보통 Loki가 있는 네임스페이스의 네트워크 정책이 대시보드를 허용하지 않을 때입니다. 클러스터 관리자가 아래 규칙을 그 정책의 ingress에 더하면 됩니다(대시보드는 클러스터에 쓰지 않음).", en: "No connection at all (refused, no route, no name, the connect itself timed out). Usually the network policy of Loki's namespace does not allow the dashboard. The cluster admin adds the rule below to that policy's ingress (the dashboard writes nothing to the cluster)." },
  "ob.hm.loki.busy": { ko: "Loki가 바쁨 (연결은 됨)", en: "Loki busy (reachable)" },
  "ob.hm.lokiHint.busy": { ko: "Loki에 연결은 되지만(/ready 응답) 조회가 25초 안에 끝나지 않았거나 과부하 응답(499·5xx)을 받았습니다 — 네트워크 정책 문제가 아닙니다. 보통 Grafana 로그 알림 조회가 Loki의 동시 처리 칸을 채울 때입니다(Grafana 'Loki 조회·수집 상태' 대시보드의 대기열·동시 처리). 대시보드는 1분 동안 다시 묻지 않습니다(Loki 부하를 더하지 않음) — 그 뒤 새로 고침하거나 기간을 줄이세요.", en: "Loki is reachable (/ready answers) but the query did not finish within 25 s or got an overload answer (499 / 5xx) — not a network policy. Usually Grafana's log alert queries are filling Loki's concurrency (Grafana's Loki query health dashboard: queue and in-flight). The dashboard does not ask again for a minute (no added load) — then refresh or shorten the range." },
  "ob.hm.lokiRetry": { ko: "다음 조회는 {at} 이후.", en: "Next read after {at}." },
  "ob.hm.lokiCause": { ko: "원인: {msg}", en: "Cause: {msg}" },
  "ob.hm.lokiHint.failed": { ko: "잠시 뒤 다시 시도하세요.", en: "Try again shortly." },
  "hb.ld.title": { ko: "드롭된 흐름 (hubble-flow-exporter → Loki)", en: "Dropped flows (hubble-flow-exporter → Loki)" },
  "hb.ld.reason": { ko: "드롭 이유", en: "Drop reason" },
  "hb.ld.none": { ko: "이 기간에 드롭된 흐름 없음 (흐름 줄 {n}개)", en: "No dropped flows in this window ({n} flow lines)" },
  "hb.ld.basis": { ko: "exporter가 보낸 흐름 줄 {n}개 기준 — TCP·UDP의 DROPPED만(ICMPv6 없음), 최대 2,000줄.", en: "From {n} flow lines the exporter shipped — TCP/UDP DROPPED only (no ICMPv6), at most 2,000 lines." },
  "hb.ld.broken": { ko: "드롭 흐름 파이프라인이 끊긴 것 같음", en: "The drop-flow pipeline looks broken" },
  "hb.ld.brokenHint": { ko: "Hubble 메트릭(AMW)은 이 기간에 드롭을 셌는데 Loki에는 흐름 줄이 없습니다 — hubble-flow-exporter·hubble-relay 상태(Cilium 업그레이드 뒤 Hubble 포트, 지워진 노드를 가리키는 릴레이)를 확인하세요.", en: "Hubble metrics (AMW) counted drops in this window but Loki holds no flow lines — check hubble-flow-exporter and hubble-relay (the Hubble port after a Cilium upgrade, a relay pointing at deleted nodes)." },
  "hb.ld.relay": { ko: "릴레이 NODE_ERROR {n}건", en: "{n} relay NODE_ERROR lines" },
  "hb.ld.relayHint": { ko: "hubble-relay가 일부 노드의 Hubble에 닿지 못했습니다 — 그 노드의 흐름이 빠졌을 수 있습니다.", en: "hubble-relay could not reach Hubble on some nodes — their flows may be missing." },
  "hb.audit.title": { ko: "정책을 강제하면 막힐 연결", en: "Connections enforcing would block" },
  "hb.audit.hint": { ko: "Cilium이 새 연결마다 남기는 '허용한 규칙'으로 판정합니다. 이름 있는 정책이 허용한 연결은 강제해도 통과하고, '모두 허용(allow-any)' 규칙으로만 통과한 연결은 기본 거부 정책이 걸리면 막힙니다. 일반 흐름 기록에는 정책 일치가 없어(policy-verdict:none) 판정에 쓰지 않습니다.", en: "Judged from the rule Cilium records as allowing each new connection. Connections a named policy allows still pass when enforced; connections passed only by the allow-any rule are blocked once a default-deny policy applies. Trace records carry no policy match (policy-verdict:none) and are not used." },
  "hb.audit.estimate": { ko: "추정값", en: "Estimate" },
  "hb.audit.estimateHint": { ko: "이 Cilium은 허용한 규칙을 기록하지 않습니다(1.15 미만). 일치 종류만으로 추정했습니다.", en: "This Cilium does not record the allowing rule (before 1.15). Estimated from the match type only." },
  "hb.audit.kind.auditOnly": { ko: "강제하면 막힘", en: "Blocked when enforced" },
  "hb.audit.kind.policy": { ko: "정책이 허용", en: "Allowed by a policy" },
  "hb.audit.kind.default": { ko: "항상 허용 (프로브 등)", en: "Always allowed (probes …)" },
  "hb.audit.kind.dropped": { ko: "지금 정책이 차단", en: "Dropped by policy now" },
  "hb.audit.kind.unknown": { ko: "판정 불가", en: "Undetermined" },
  "hb.audit.window": { ko: "새 연결 {n}건 · {from} – {to} (노드 버퍼에 남은 것만 — 오래 열린 연결·드문 흐름은 빠질 수 있으니 업무 주기 전체를 보세요)", en: "{n} new connections · {from} – {to} (only what is left in the node buffers — long-lived connections and rare flows may be missing; watch a whole business cycle)" },
  "hb.audit.byPolicy": { ko: "허용한 정책", en: "Allowing policies" },
  "hb.audit.col.workload": { ko: "워크로드", en: "Workload" },
  "hb.audit.col.peer": { ko: "상대 (DNS 이름·IP)", en: "Peer (DNS name · IP)" },
  "hb.audit.col.connections": { ko: "연결 수", en: "Connections" },
  "hb.audit.col.lastSeen": { ko: "마지막", en: "Last seen" },
  "hb.audit.noName": { ko: "DNS 이름 없음 — FQDN 규칙으로는 허용 불가", en: "No DNS name — an FQDN rule cannot allow it" },
  "hb.audit.none": { ko: "강제해도 막힐 연결이 보이지 않음", en: "No connection would be blocked" },
  "hb.audit.noneHint": { ko: "이 구간의 새 연결은 모두 이름 있는 정책이나 항상 허용되는 규칙으로 통과했습니다.", en: "Every new connection in this span passed by a named policy or an always-allowed rule." },

