  "ld.lc.cause.maintenance": { ko: "진행 중인 Service Health 계획 유지보수가 이 리소스를 영향 대상으로 나열함", en: "An active Service Health planned-maintenance event lists this resource as impacted" },
  "ld.lc.cause.unknown": { ko: "아직 기록 없음 — 변경 기록은 보통 5분 안에 들어오며, 들어오면 다음 갱신에 표시됩니다", en: "Nothing recorded yet — change records usually arrive within 5 minutes and show on a later refresh" },
