  "ld.lc.note": { ko: "지금 상태는 이번 갱신에 Azure에서 읽은 값입니다. 진행 중이어도 카드 상태 색과 장애 영향에는 쓰지 않습니다(업데이트 중 ≠ 중단).", en: "The state is what Azure returned on this refresh. In progress never changes the card's status colour or fault impact (updating ≠ down)." },
  "ld.lc.noteUnknown": { ko: "원인은 기록이 있을 때만 말합니다 — 상태 단어만으로 사용자 변경·유지보수라고 하지 않습니다.", en: "A cause is named only from a record — never from the state word alone." },
  "ld.lc.chipHint": { ko: "이번 갱신에 Azure에서 읽은 작업 상태 (원인은 기록이 있을 때만)", en: "Operation state read on this refresh (a cause only from a record)" },
