  "ld.lbin.fe.notMeasured": { ko: "미측정 — Azure가 이 프런트엔드 값을 주지 않음", en: "Not measured — Azure returned no value for this frontend" },
  "ld.lbin.fe.metricsOff": { ko: "미측정 — 메트릭을 읽지 못함", en: "Not measured — metrics could not be read" },
  "ld.lbin.fe.zero": { ko: "바이트 0 (1시간) — UDR 경유 트래픽은 집계되지 않음", en: "0 bytes (last hour) — traffic via a UDR is not counted" },
  "ld.lbin.fe.noRule": { ko: "이 프런트엔드에 부하 분산 규칙 없음", en: "No load-balancing rule on this frontend" },
  "ld.lbin.probeNote": { ko: "데이터 경로 가용성·상태 프로브는 Azure의 합성 프로빙이며 사용자 트래픽이 아닙니다. 데이터 경로 가용성은 부하 분산 규칙이 있는 프런트엔드에서만 생성됩니다.", en: "Data path availability and health probes are Azure synthetic probing, not user traffic; data path availability exists only on frontends with load-balancing rules." },
  "ld.lbin.udr": { ko: "UDR 다음 홉 (구성)", en: "UDR next hop (configuration)" },
  "ld.lbin.udr.none": { ko: "이 LB 프런트엔드를 다음 홉으로 쓰는 UDR 없음 — 읽은 구독 범위", en: "No UDR uses these frontends as next hop — subscriptions read" },
  "ld.lbin.udr.unreadable": { ko: "경로 테이블을 읽지 못함", en: "Route tables could not be read" },
  "ld.lbin.udr.more": { ko: "외 {count}", en: "+{count} more" },
  "ld.lbin.udr.note": { ko: "구성상 경로입니다. 유효 경로(BGP·더 긴 접두사)가 우선할 수 있습니다. 이 경로로 온 트래픽은 LB 바이트·SYN 메트릭에 잡히지 않습니다.", en: "Configured routes; effective routes (BGP, longer prefixes) may take precedence. Traffic on these routes is not in the LB byte / SYN metrics." },
  "ld.lbin.fe.bytes": { ko: "{bytes} 받음 · SYN 패킷 {syn}", en: "{bytes} received · {syn} SYN packets" },
  "ld.lbin.metricNote": { ko: "LB 메트릭(ByteCount·SYNCount, 방향 In)입니다. 호출자별로 나눌 수 없고, UDR로 NVA·방화벽을 거쳐 온 트래픽은 Azure가 집계하지 않습니다. SYN 수는 연결 수가 아닙니다.", en: "Load balancer metrics (ByteCount, SYNCount, direction In). They cannot be split by caller, Azure does not count traffic that arrives through a UDR (NVA / firewall), and SYN packets are not connections." },
  "ld.lbin.configured": { ko: "구성상 호출자", en: "Configured callers" },
  "ld.lbin.configuredWhy": { ko: "백엔드 풀 주소 = 이 LB의 프런트엔드 IP (구성)", en: "Its backend pool holds this LB's frontend IP (configuration)" },
  "ld.lbin.configuredNone": { ko: "구성에서 찾은 호출자 없음 — App Gateway·Front Door 백엔드 풀 기준 (Private Link Service는 아직 읽지 않음)", en: "No caller found in configuration — App Gateway / Front Door backend pools (Private Link Service is not read yet)" },
  "ld.lbin.observed": { ko: "관측된 호출자 (VNet 흐름 로그)", en: "Observed callers (VNet flow logs)" },
  "ld.lbin.flow.empty": { ko: "최근 {hours}시간 흐름 로그에 이 프런트엔드로 간 기록 없음 — 흐름 로그가 켜진 VNet에서 보낸 것만 보입니다", en: "No flow to these frontends in the last {hours} h — only senders in VNets with flow logs are seen" },
  "ld.lbin.notCallers": { ko: "피어링된 VNet·온프레미스 사이트는 도달 가능할 뿐 호출자로 그리지 않습니다. DNS 레코드는 호출 근거로 쓰지 않습니다.", en: "Peered VNets and on-premises sites can reach it — they are not drawn as callers. DNS records are not evidence of a call." },
  "ld.lbin.chip.callers": { ko: "앞단 {count}", en: "{count} in front" },
  "ld.lbin.chip.callers.hint": { ko: "이 내부 LB로 보내는 호출자 — 구성(백엔드 풀)과 흐름 로그에서 확인된 것", en: "Callers of this internal LB — from configuration (backend pools) and flow logs" },
  "ld.lbin.chip.sourceUnknown": { ko: "인입 있음 · 출처 미확인", en: "Inbound · source unknown" },
  "ld.lbin.chip.sourceUnknown.hint": { ko: "최근 1시간 이 LB의 사설 프런트엔드로 트래픽이 들어왔지만(메트릭), 누가 보냈는지는 구성·흐름 로그로 확인되지 않음", en: "Traffic reached a private frontend in the last hour (metrics), but no configuration or flow log says who sent it" },
  "ld.lbin.chip.udr": { ko: "UDR 다음 홉 · 서브넷 {count}", en: "UDR next hop · {count} subnets" },
  "ld.lbin.chip.udr.hint": { ko: "경로 테이블 {rt}개가 이 LB의 사설 프런트엔드 IP를 다음 홉(가상 어플라이언스)으로 지정, 연결 서브넷 {count}개 (구성). Azure 문서: UDR(NVA·방화벽)로 내부 LB에 온 트래픽은 바이트·패킷·SYN 메트릭에 잡히지 않음", en: "{rt} route tables name this LB's private frontend IP as next hop (virtual appliance), {count} associated subnets (configuration). Azure: traffic reaching an internal LB through a UDR (NVA / firewall) is not captured by byte, packet or SYN metrics" },
  "ld.lbin.chip.zeroBytes": { ko: "LB 바이트 0 (1h)", en: "LB bytes 0 (1 h)" },
  "ld.lbin.chip.zeroBytes.hint": { ko: "최근 1시간 사설 프런트엔드 ByteCount(In) 측정값 0. UDR 경유 트래픽은 이 메트릭에 잡히지 않으므로 미사용을 뜻하지 않음", en: "ByteCount (In) on the private frontends measured 0 in the last hour. Traffic via a UDR is not in this metric, so this does not mean unused" },
  "ld.lbin.chip.notMeasured": { ko: "LB 바이트 미측정", en: "LB bytes not measured" },
  "ld.lbin.chip.notMeasured.hint": { ko: "사설 프런트엔드의 수신 메트릭을 아직 받지 못함 — 측정 없음은 0이 아님", en: "No inbound metric for the private frontends yet — not measured is not 0" },
