  "ld.focus.hint": { ko: "켜면 리소스에 마우스를 올렸을 때 연결된 것만 남기고 나머지를 흐리게 합니다. 끄면 전체가 그대로 보이고 연결선만 강조됩니다", en: "On: hovering a resource dims everything it is not linked to. Off: the whole picture stays visible and only its lines are highlighted" },
