  "notify.map.rule.service": { ko: "Azure 보낸 서비스 — Service Health·Resource Health = 장애, 활동 로그 Security·Policy = 보안, Administrative·Autoscale = 변경", en: "Azure monitoring service — Service Health · Resource Health = incident, activity log Security · Policy = security, Administrative · Autoscale = change" },
