  "notify.map.sevRule": { ko: "심각도: Azure Sev0→SEV1, Sev1→SEV2, Sev2→SEV3, Sev3·4→SEV4 · Grafana 라벨 sev1~4 그대로(critical→SEV1, error→SEV2, warning→SEV3, info→SEV4).", en: "Severity: Azure Sev0→SEV1, Sev1→SEV2, Sev2→SEV3, Sev3·4→SEV4 · Grafana label sev1–4 as is (critical→SEV1, error→SEV2, warning→SEV3, info→SEV4)." },
