  "ob.slo.kindHint.availability": { ko: "5xx로 답하지 않은 요청 / 전체 요청 (/actuator 제외)", en: "Requests not answered 5xx / all requests (not /actuator)" },
  "ob.slo.kindHint.latency": { ko: "버킷 경계 안에 끝난 요청 / 전체 요청 (1xx·/actuator 제외, 보간 없음)", en: "Requests done within the bucket boundary / all (no 1xx, no /actuator, no interpolation)" },
