  "ob.slo.resetCardHint": { ko: "이 서비스의 에러 버짓을 지금(또는 고른 시각)부터 다시 셉니다. 소진율 경보는 '지금'을 재므로 초기화되지 않습니다. 사유는 변경 기록에 남습니다.", en: "Counts this service's error budget again from now (or a picked time). Burn-rate alerts measure now and are not reset. The reason goes to the history." },
  "ob.slo.g.source.platform": { ko: "플랫폼 설정", en: "Platform settings" },
  "ob.slo.set.loading": { ko: "SLO 설정을 읽는 중…", en: "Reading the SLO settings…" },
