  "ob.slo.set.saved": { ko: "저장했어요 — SLO 값을 새 목표로 다시 읽었습니다.", en: "Saved — the SLOs were read again with the new targets." },
  "ob.slo.set.conflict": { ko: "다른 사람이 먼저 저장했어요. 최신 설정을 불러왔으니 다시 바꿔 주세요.", en: "Someone saved first. The latest settings are loaded — make your change again." },
  "ob.slo.set.memoryTitle": { ko: "이 서버는 설정을 메모리에만 둡니다", en: "This server keeps the settings in memory only" },
  "ob.slo.set.memory": { ko: "저장 폴더(AUD_ARRANGEMENT_DIR)가 없어 재시작하면 목표와 초기화가 사라집니다. 오래 쓸 목표는 연결 파일에도 적어 두세요.", en: "Without a storage folder (AUD_ARRANGEMENT_DIR) the targets and resets are gone after a restart. Write lasting targets in the connection file too." },
  "ob.slo.set.readOnly": { ko: "보기 전용입니다 — 목표와 초기화는 운영자(AUD.Operator) 이상만 바꿀 수 있어요.", en: "Read-only — operators (AUD.Operator) and above change targets and resets." },
  "ob.slo.set.dirty": { ko: "저장하지 않은 변경이 있어요", en: "Unsaved changes" },
  "ob.slo.set.lastSaved": { ko: "마지막 저장 {at} · {by}", en: "Last saved {at} · {by}" },
  "ob.slo.set.never": { ko: "플랫폼에서 정한 값 없음 — 모두 연결 파일·기본값을 따릅니다", en: "Nothing set here — everything follows the connection file and the defaults" },
  "ob.slo.set.errors": { ko: "고칠 칸 {n}", en: "{n} fields to fix" },
  "ob.slo.set.discard": { ko: "되돌리기", en: "Discard" },
  "ob.slo.set.save": { ko: "저장", en: "Save" },
  "ob.slo.set.cancel": { ko: "취소", en: "Cancel" },
  "ob.slo.set.clusterTitle": { ko: "클러스터 기본 목표", en: "Cluster defaults" },
  "ob.slo.set.clusterSub": { ko: "모든 서비스에 — 서비스별 값이 있으면 그 값", en: "Every service — unless it has its own" },
  "ob.slo.set.precedence": { ko: "우선순위: 서비스별(플랫폼) › 서비스별(연결 파일) › 클러스터 기본(플랫폼) › 연결 파일 › 기본값.", en: "Precedence: per service (platform) › per service (connection file) › cluster default (platform) › connection file › defaults." },
  "ob.slo.set.fileGuide": { ko: "연결 파일로 정하기", en: "Set in the connection file" },
  "ob.slo.set.window": { ko: "SLO 기간", en: "SLO window" },
  "ob.slo.set.availability": { ko: "가용성 목표", en: "Availability target" },
