  "ob.slo.set.noBucket": { ko: "이 기준 이하의 히스토그램 경계가 없어 지연을 셀 수 없어요", en: "No histogram boundary at or under this — latency cannot be counted" },
  "ob.slo.set.badThreshold": { ko: "1–120000 사이 정수(ms)", en: "A whole number 1–120000 (ms)" },
  "ob.slo.set.excludeUris": { ko: "세지 않을 URI", en: "URIs not counted" },
  "ob.slo.set.excludeHint": { ko: "한 줄에 하나 — Micrometer uri 태그와 똑같은 문자열(패턴 아님)", en: "One per line — exactly the Micrometer uri tag (not a pattern)" },
  "ob.slo.set.badUris": { ko: "50개, 각 300자까지", en: "Up to 50, 300 characters each" },
  "ob.slo.set.resetTitle": { ko: "에러 버짓 초기화", en: "Error budget reset" },
  "ob.slo.set.resetSub": { ko: "장애를 고치고 회고를 마친 뒤", en: "After an incident is fixed and reviewed" },
  "ob.slo.set.resetWhat": { ko: "고른 시각 이전의 실패를 예산 계산에서 뺍니다. 그 서비스의 SLO 값과 예산은 초기화 시각부터 지금까지(최대 {days}일)로 셉니다. 소진율 경보(1시간·6시간·3일)는 '지금'을 재므로 그대로입니다.", en: "Failures before the picked time leave the budget: the service's SLO and budget are counted from the reset to now (at most {days} days). Burn-rate alerts (1 h · 6 h · 3 d) measure now and stay as they are." },
  "ob.slo.set.resetFoot": { ko: "초기화는 SLO 기간이 지나면 저절로 끝나고, 언제든 취소할 수 있어요. 누가·언제·왜는 변경 기록에 남습니다.", en: "A reset ends by itself when it leaves the SLO window and can be undone any time. Who, when and why go to the history." },
  "ob.slo.set.resetDone": { ko: "초기화했어요 — SLO 값을 다시 읽었습니다.", en: "Reset — the SLOs were read again." },
