  "ob.slo.set.servicesFoot": { ko: "빈 칸 = 위(클러스터 기본·연결 파일·기본값)를 따름. 지연 기준과 목표 중 하나만 바꾸면 다른 하나는 지금 값을 그대로 씁니다.", en: "Empty = inherit (cluster default, connection file, defaults). Change only the latency threshold or target and the other keeps its current value." },
