  "ob.slo.set.err.slo_reset_invalid": { ko: "초기화 요청이 올바르지 않아요 (서비스·사유 3–200자).", en: "The reset request is not valid (service, reason 3–200 characters)." },
  "ob.slo.set.err.slo_reset_time": { ko: "시각은 지금부터 30일 전 사이여야 해요.", en: "The time must be between now and 30 days ago." },
  "ob.slo.set.err.slo_reset_full": { ko: "초기화는 클러스터당 20개까지예요 — 끝난 것을 취소해 주세요.", en: "Up to 20 resets per cluster — undo ones that ended." },
